mapper.select:
select *
from daily_plan
where user_id = #{userId}
  and plan_date = #{planDate}
limit 1

select *
from daily_plan
where user_id = #{userId}
  and plan_date between #{startDate} and #{endDate}
order by plan_date asc, id asc

select * from daily_plan_item where plan_id in
#{planId}
order by sort_order asc, id asc

mapper.update:
update daily_plan
set plan_name = #{planName},
    plan_type = #{planType}
where id = #{id}
  and user_id = #{userId}

mapper.select:
select *
from weekly_plan_template
where user_id = #{userId}
  and template_name = #{templateName}
limit 1

select *
from weekly_plan_template
where id = #{templateId}
  and user_id = #{userId}
limit 1

mapper.update:
update weekly_plan_template
set source_plan_name = #{sourcePlanName}
where id = #{id}
  and user_id = #{userId}

mapper.delete:
delete
from weekly_plan_template
where id = #{templateId}
  and user_id = #{userId}

mapper.select:
select *
from annual_plan_segment
where user_id = #{userId}
  and plan_year = #{planYear}
order by sort_order asc, update_time asc, id asc

select *
from annual_plan_segment
where id = #{segmentId}
  and user_id = #{userId}
limit 1

select *
from annual_plan_segment
where client_entity_id = #{clientEntityId}
  and user_id = #{userId}
limit 1

mapper.delete:
delete from annual_plan_segment
